Item.method_code:
const showDialog = () => {
	const dialogMessage = aras.getResource('', 'item_methods_ex.changes_not_saved');
	const text = aras.getResource('', 'common.discard');
	const title = aras.getResource('', 'item_methods_ex.unsaved_changes');
	const okButtonText = aras.getResource('', 'common.save');
	const actionName = 'discard';
	const dialogParams = {
		additionalButtons: [{ text, actionName }],
		buttonsOrdering: ['ok', 'discard', 'cancel'],
		okButtonText,
		title
	};

	return ArasModules.Dialog.confirm(dialogMessage, dialogParams);
};

const { getLayout } = options;
const layout = getLayout();
const result = await showDialog();
if (!result || result === 'cancel') {
	return false;
}
if (result === 'ok') {
	const tocEditorSaved = await layout.saveTOC();
	if (!tocEditorSaved) {
		return false;
	}
} else {	
	layout.actions.discardChanges();
}

layout.destroy();

return true;
